UPDATE lessons SET title='Year 3, Week 2, Lesson 3: Nouns, verbs and adjectives', data=json_patch(data,'{"child_mission":"Choose nouns, verbs and adjectives to make sentences precise and readable.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Keep the independent response and two written check responses; record oral retelling or performance where required by the task.","explicit_teaching":null,"extension":"Create a new example using a completely different character or setting, show the same skill, then explain to another person how you checked its accuracy.","follow_up_challenges":null,"guided_practice":"WE DO — attempt each prompt before comparing to the feedback.\n1. Find two nouns in \"A pelican balanced on the post\".\nCOMPARE: Pelican and post are nouns. Balanced is an action verb.\n2. Swap \"went\" for a more specific verb in \"The cyclist went downhill\".\nCOMPARE: \"The cyclist coasted downhill\" explains the manner of movement more precisely.\n3. Add one helpful adjective to \"The lantern hung above the door\".\nCOMPARE: \"The cracked lantern hung above the door\" gives condition. Many other precise choices are possible.\n4. Improve \"The car moved on the road\" with one precise noun, verb and adjective.\nCOMPARE: Example: \"The rusty ute rattled along the gravel road.\" Ute and road are nouns; rattled is verb; rusty and gravel specify details.","hoard_words":null,"independent_task":"YOU DO — complete the following substantial original task, not a copied model.\nAnalyse the nouns, main verb and adjectives in \"The determined ranger carried a heavy bag along the dusty track.\" Then revise three sentences of your own about a beach, a library and a storm. Label one noun, verb and adjective in each revised sentence and explain the improvement.","interactive_activities":null,"learning_area":"English","learning_intention":"Choose nouns, verbs and adjectives to make sentences precise and readable.","lesson_number":3,"lesson_role":"Language and spelling","materials":["Paper or typing area","Pencil for optional evidence"],"offline_alternative":"Use paper to copy only the original independent prompt; have the child respond in writing or orally as required. Save a photograph or brief parent observation for the learning record.","outcome_codes":["EN2-CWT-01"],"parent_notes":"Parent: Marking guidance for the independent task: Analyse the nouns, main verb and adjectives in \"The determined ranger carried a heavy bag along the dusty track.\" Then revise three sentences of your own about a beach, a library and a storm. Label one noun, verb and adj Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Pelican and post are nouns. Balanced is an action verb. Reasoning: I used noun by attending to verb and point to the words or events th rather than copying the worked model.\n\nParent: Written model 2: Common error: A word is not a noun just because it appears early in a sentence. Correction: Pelican and post are nouns. Balanced is an action verb. Why: the correction restores accurate use of noun.\n\nParent: Likely misconception: A word is not a noun just because it appears early in a sentence. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating noun on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with noun, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Require independently produced work with a specific supporting detail. / Require misconception + correction + purpose-linked reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"Pelican and post are nouns. Balanced is an action verb. This matches the lesson skill for noun.","options":["Copy the worked example and call it independent work.","Pelican and post are nouns. Balanced is an action verb.","A word is not a noun just because it appears early in a sentence.","Ignore the task and invent an unrelated answer."],"question":"Swap \"went\" for a more specific verb in \"The cyclist went downhill\". Which response is most accurate?","type":"multiple_choice"},{"correct_index":2,"explanation":"A word is not a noun just because it appears early in a sentence. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Pelican and post are nouns. Balanced is an action verb.","Careful use of verb and point to the words or events th with clear evidence.","A word is not a noun just because it appears early in a sentence.","Choose nouns, verbs and adjectives to make sentences precise and readable."],"question":"Which statement is a common mistake when practising noun?","type":"multiple_choice"},{"correct_index":1,"explanation":"Understanding is shown by new evidence and named verb and point to the words or events th, not by copying the model.","options":["Treat a missing detail as a proven fact.","Apply the idea with new evidence and name the verb and point to the words or events th used.","Repeat the worked example wording with no new evidence.","Choose randomly because any option could be right."],"question":"A learner is practising noun. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":0,"explanation":"The skill is shown by quoting or pointing to wording that carries noun.","options":["Point to exact words in the sentence that show noun and say what they do.","Ignore the sentence and invent a more exciting event.","Say the writing is good without naming any words.","A word is not a noun just because it appears early in a sentence."],"question":"Read: \"After the blackout, Tess lit a candle and read the crumpled note.\" Which choice best uses noun from this lesson?","type":"multiple_choice"},{"correct_index":2,"explanation":"The correct statement applies the language skill; the others miss the evidence.","options":["Ignore the task and invent an unrelated answer.","Copy the worked example and call it independent work.","Pelican and post are nouns. Balanced is an action verb.","A word is not a noun just because it appears early in a sentence."],"question":"Which statement correctly applies the lesson idea about noun?","type":"multiple_choice"},{"correct_index":3,"explanation":"Start from a specific textual clue, then explain its effect.","options":["Guess from the title alone with no textual clue.","Copy a model sentence from another story unchanged.","Treat a missing detail as a proven fact.","Locate a specific word, phrase or structural clue before deciding."],"question":"In a new text, what should you do first to practise verb and point to the words or events th?","type":"multiple_choice"},{"correct_index":3,"explanation":"Repair means fixing meaning or evidence, not padding.","options":["Add adjectives without fixing the wrong idea.","Make the answer longer while keeping the same mistake.","Delete the evidence that disagreed with your first guess.","Change the inaccurate idea or missing evidence, not only the length."],"question":"Which revision actually repairs meaning?","type":"multiple_choice"},{"correct_index":3,"explanation":"Transfer needs fresh material with an explained language choice.","options":["Retype the worked model as the final answer.","Change fonts and claim the work is new.","A word is not a noun just because it appears early in a sentence.","Use a fresh sentence or text and explain one precise choice about noun."],"question":"Which response shows transfer of noun to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require independently produced work with a specific supporting detail.","question":"Produce a fresh example demonstrating noun on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Original response on new material: Pelican and post are nouns. Balanced is an action verb. Reasoning: I used noun by attending to verb and point to the words or events th rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require misconception + correction + purpose-linked reason.","question":"Name one likely error with noun, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Common error: A word is not a noun just because it appears early in a sentence. Correction: Pelican and post are nouns. Balanced is an action verb. Why: the correction restores accurate use of noun.","type":"short_answer"}],"resources":null,"response_prompt":"Submit your original independent work and your brief explanation of the key choices you made.","review_status":"unreviewed","seed_key":"s2-eng-y3-w02-l3","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; compare the existing Coming Soon card and official syllabus content points before marking verified.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise noun.","Read the mission before you start writing or speaking.","Your goal is: Choose nouns, verbs and adjectives to make sentences precise and readable."],"guided":["Attempt each guided prompt without looking ahead.","Compare your attempt with the supplied specific feedback.","Guided comparison: \"The cyclist coasted downhill\" explains the manner of movement more precisely."],"learn":["Study the first worked demonstration carefully.","Name the exact words or events that make it work.","Demonstration: \"The mechanic repaired a bicycle.\" Mechanic and bicycle name things; repaired tells the action."],"quiz":["Read the whole question and eliminate misconceptions.","Prefer the option that quotes or uses actual evidence.","Likely trap: Adding four similar adjectives can weaken rather than strengthen a sentence."],"submit":["Include your own response and a short reason.","Proofread names, sequence and punctuation before sending.","Success looks like: Choose nouns, verbs and adjectives to make sentences precise and readable."],"teach0":["Focus on name people, places and things with nouns.","Hold this teaching point: A noun names a person, place, object or idea. Some nouns are common (river), while names of particular people or places ","Worked comparison: Pelican and post are nouns. Balanced is an action verb."],"teach1":["Focus on show actions and states with verbs.","Hold this teaching point: Verbs help a sentence tell what happens or what something is like. Choose a strong verb when it adds meaning.","Worked comparison: \"The cyclist coasted downhill\" explains the manner of movement more precisely."],"teach2":["Focus on describe useful properties with adjectives.","Hold this teaching point: An adjective adds information about a noun. Choose details readers need rather than filling every sentence with colour w","Worked comparison: \"The cracked lantern hung above the door\" gives condition. Many other precise choices are possible."],"teach3":["Focus on combine all three without confusing the reader.","Hold this teaching point: Find the main noun and verb first, then choose whether a descriptive word adds valuable detail. Read the revision aloud.","Worked comparison: Example: \"The rusty ute rattled along the gravel road.\" Ute and road are nouns; rattled is verb; rusty and gravel specif"],"write":["Use the independent instructions, not the model words.","Give an original response and the reason behind it.","Independent reminder: Analyse the nouns, main verb and adjectives in \"The determined ranger carried a heavy bag along the dusty track.\" Then revise three sentences of your own about "]},"subject":"English","success_criteria":["I can use noun with a specific example from this lesson.","I can identify verb and point to the words or events that support it.","I can practise adjective independently on a new prompt.","I can notice precise needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding. Apply the lesson idea with evidence.","options":["Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail.","Use the example and explain the clue or language choice before trying noun independently."],"question":"Which choice best shows accurate use of this idea about noun?","type":"multiple_choice"},"example":"WATCH MY THINKING\n\"The mechanic repaired a bicycle.\" Mechanic and bicycle name things; repaired tells the action.\n\nYOUR SMALL TRY\nFind two nouns in \"A pelican balanced on the post\".\n\nCOMPARE AND CORRECT\nPelican and post are nouns. Balanced is an action verb.","explain":"A noun names a person, place, object or idea. Some nouns are common (river), while names of particular people or places are proper nouns (Murray River).\n\nA noun names a person, place, object or idea. Some nouns are common (river), while names of particular people or places are proper nouns (Murray River). This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA word is not a noun just because it appears early in a sentence. Re-read the prompt and correct the misunderstanding before moving on.","title":"Name people, places and things with nouns","visual":[{"alt":"Sentence parts labelled: nouns mechanic and bicycle with verb repaired.","caption":"Nouns name people or things; the verb tells the action.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Nouns</text><text x=\"28\" y=\"78\">mechanic, bicycle</text><text x=\"358\" y=\"42\">Verb</text><text x=\"358\" y=\"78\">repaired</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I read the first example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or events that carry the meaning before you copy a conclusion.","who":"juno"},{"text":"So I should try the small prompt myself, then compare it with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: \"The mechanic repaired a bicycle.\" Mechanic and bicycle name things; repaired tells the action. Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I read the first example, but I am not sure which detail matters most.\nJuno: Name the exact words or events that carry the meaning before you copy a conclusion.\nPip: So I should try the small prompt myself, then compare it with the feedback.\nJuno: Pause here. Use this model: \"The mechanic repaired a bicycle.\" Mechanic and bicycle name things; repaired tells the action. Then write your own attempt."}}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding. Apply the lesson idea with evidence.","options":["Use the example and explain the clue or language choice before trying verb independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which choice best shows accurate use of this idea about noun?","type":"multiple_choice"},"example":"WATCH MY THINKING\n\"The puppy moved\" is vague; \"The puppy scampered\" suggests quick, playful steps. \"The puppy was tired\" uses was to tell a state.\n\nYOUR SMALL TRY\nSwap \"went\" for a more specific verb in \"The cyclist went downhill\".\n\nCOMPARE AND CORRECT\n\"The cyclist coasted downhill\" explains the manner of movement more precisely.","explain":"Verbs help a sentence tell what happens or what something is like. Choose a strong verb when it adds meaning.\n\nVerbs help a sentence tell what happens or what something is like. Choose a strong verb when it adds meaning. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nDo not assume every verb describes visible movement; is and seems can also be verbs. Re-read the prompt and correct the misunderstanding before moving on.","title":"Show actions and states with verbs","visual":[{"alt":"Vague sentence The bird flew beside a precise revision naming a startled rosella.","caption":"Choose a specific noun and verb, then add an adjective only if it helps.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Vague draft</text><text x=\"28\" y=\"78\">The bird flew.</text><text x=\"358\" y=\"42\">Precise revision</text><text x=\"358\" y=\"78\">The startled rosella darted between branch</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding. Apply the lesson idea with evidence.","options":["Ignore the task and choose an unrelated detail.","Use the example and explain the clue or language choice before trying adjective independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact."],"question":"Which choice best shows accurate use of this idea about noun?","type":"multiple_choice"},"example":"WATCH MY THINKING\n\"The slippery path\" warns about a surface. In \"The slippery, narrow path twisted uphill\", both adjectives help picture the danger and shape.\n\nYOUR SMALL TRY\nAdd one helpful adjective to \"The lantern hung above the door\".\n\nCOMPARE AND CORRECT\n\"The cracked lantern hung above the door\" gives condition. Many other precise choices are possible.","explain":"An adjective adds information about a noun. Choose details readers need rather than filling every sentence with colour words.\n\nAn adjective adds information about a noun. Choose details readers need rather than filling every sentence with colour words. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nAdding four similar adjectives can weaken rather than strengthen a sentence. Re-read the prompt and correct the misunderstanding before moving on.","title":"Describe useful properties with adjectives"},{"check":{"correct_index":2,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding. Apply the lesson idea with evidence.","options":["Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail.","Use the example and explain the clue or language choice before trying precise independently.","Copy every sentence exactly without explaining it."],"question":"Which choice best shows accurate use of this idea about noun?","type":"multiple_choice"},"example":"WATCH MY THINKING\nDraft: \"The bird flew.\" Revision: \"The startled rosella darted between branches.\" Nouns: rosella, branches. Verb: darted. Adjective: startled.\n\nYOUR SMALL TRY\nImprove \"The car moved on the road\" with one precise noun, verb and adjective.\n\nCOMPARE AND CORRECT\nExample: \"The rusty ute rattled along the gravel road.\" Ute and road are nouns; rattled is verb; rusty and gravel specify details.","explain":"Find the main noun and verb first, then choose whether a descriptive word adds valuable detail. Read the revision aloud.\n\nFind the main noun and verb first, then choose whether a descriptive word adds valuable detail. Read the revision aloud. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nDo not mistake an adverb describing a verb for an adjective describing a noun. Re-read the prompt and correct the misunderstanding before moving on.","title":"Combine all three without confusing the reader"}],"title":"Year 3, Week 2, Lesson 3: Nouns, verbs and adjectives","unit_number":1,"unit_title":"Narrative: story elements and planning","week":2,"week_in_unit":2,"word_challenges":null,"worked_example":"I DO — \"The mechanic repaired a bicycle.\" Mechanic and bicycle name things; repaired tells the action.\n\nNow look for the exact evidence in the words or actions. \"The puppy moved\" is vague; \"The puppy scampered\" suggests quick, playful steps. \"The puppy was tired\" uses was to tell a state.","worked_visuals":[{"alt":"Sentence parts labelled: nouns mechanic and bicycle with verb repaired.","caption":"Nouns name people or things; the verb tells the action.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Nouns</text><text x=\"28\" y=\"78\">mechanic, bicycle</text><text x=\"358\" y=\"42\">Verb</text><text x=\"358\" y=\"78\">repaired</text></g></svg>"},{"alt":"Vague sentence The bird flew beside a precise revision naming a startled rosella.","caption":"Choose a specific noun and verb, then add an adjective only if it helps.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Vague draft</text><text x=\"28\" y=\"78\">The bird flew.</text><text x=\"358\" y=\"42\">Precise revision</text><text x=\"358\" y=\"78\">The startled rosella darted between branch</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w02-l3' AND family_id IS NULL;
